def get_device(use_gpu: Optional[bool] = True) -> torch.device:
    if not use_gpu:
        print("Using CPU")
        return torch.device("cpu")
    if torch.cuda.is_available():
        print("Using CUDA (NVidia / AMD)")
        return torch.device("cuda")
    if torch.backends.mps.is_available():
        if platform.machine() == "arm64":
            print("Using MPS (Apple Silicon)")
            return torch.device("mps")
        else:
            print("MPS detected but not applicable on Intel Mac - falling back to CPU")
    if hasattr(torch, "xpu") and torch.xpu.is_available():
        print("Using XPU (Intel ARC / XPU)")
        return torch.device("xpu")
    try:
        import torch_directml
        if torch_directml.is_available():
            print("Using DirectML")
            return torch_directml.device()
    except ImportError:
        pass
    print("No GPU acceleration available, falling back to CPU")
    return torch.device("cpu")


# ============================================================================
# Shared building blocks (identical for both Zenith and Axiom 2.1)
# ============================================================================

class LayerNorm2d(nn.Module):
    def __init__(self, channels: int, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(1, channels, 1, 1))
        self.bias   = nn.Parameter(torch.zeros(1, channels, 1, 1))
        self.eps    = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        mean = x.mean(dim=1, keepdim=True)
        var  = (x - mean).pow(2).mean(dim=1, keepdim=True)
        x    = (x - mean) / torch.sqrt(var + self.eps)
        return x * self.weight + self.bias


class SimpleGate(nn.Module):
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x1, x2 = x.chunk(2, dim=1)
        return x1 * x2


class NAFBlock(nn.Module):
    def __init__(self, channels: int):
        super().__init__()
        self.norm1  = LayerNorm2d(channels)
        self.conv1  = nn.Conv2d(channels, channels * 2, kernel_size=1, bias=True)
        self.dwconv = nn.Conv2d(
            channels * 2, channels * 2,
            kernel_size=3, padding=1, groups=channels * 2, bias=True,
        )
        self.sg  = SimpleGate()
        self.sca = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Conv2d(channels, channels, kernel_size=1, bias=True),
        )
        self.conv2 = nn.Conv2d(channels, channels, kernel_size=1, bias=True)

        self.norm2 = LayerNorm2d(channels)
        self.ffn1  = nn.Conv2d(channels, channels * 2, kernel_size=1, bias=True)
        self.ffn2  = nn.Conv2d(channels, channels, kernel_size=1, bias=True)

        self.beta  = nn.Parameter(torch.zeros(1, channels, 1, 1))
        self.gamma = nn.Parameter(torch.zeros(1, channels, 1, 1))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        y = self.norm1(x)
        y = self.conv1(y)
        y = self.dwconv(y)
        y = self.sg(y)
        y = y * self.sca(y)
        y = self.conv2(y)
        x = x + y * self.beta

        y = self.norm2(x)
        y = self.ffn1(y)
        y = self.sg(y)
        y = self.ffn2(y)
        x = x + y * self.gamma
        return x


# ============================================================================
# Model architecture — Zenith (PixelShuffle decoder, residual output)
# ============================================================================

class NAFNetZenith(nn.Module):
    """NAFNet with PixelShuffle upsampling — used by the Zenith model."""

    def __init__(
        self,
        in_ch: int = 3,
        out_ch: int = 3,
        width: int = 32,
        enc_blk_nums: tuple = (2, 2, 4, 8),
        dec_blk_nums: tuple = (2, 2, 2, 2),
        middle_blk_num: int = 2,
        use_sigmoid: bool = True,
    ):
        super().__init__()
        self.intro   = nn.Conv2d(in_ch, width, kernel_size=3, padding=1, bias=True)
        self.ending  = nn.Conv2d(width, out_ch, kernel_size=3, padding=1, bias=True)

        self.encoders = nn.ModuleList()
        self.downs    = nn.ModuleList()
        self.decoders = nn.ModuleList()
        self.ups      = nn.ModuleList()

        ch = width
        for num in enc_blk_nums:
            self.encoders.append(nn.Sequential(*[NAFBlock(ch) for _ in range(num)]))
            self.downs.append(nn.Conv2d(ch, ch * 2, kernel_size=2, stride=2, bias=True))
            ch *= 2

        self.middle = nn.Sequential(*[NAFBlock(ch) for _ in range(middle_blk_num)])

        for num in dec_blk_nums:
            self.ups.append(nn.Sequential(
                nn.Conv2d(ch, ch * 2, kernel_size=1, bias=True),
                nn.PixelShuffle(2),
            ))
            ch //= 2
            self.decoders.append(nn.Sequential(*[NAFBlock(ch) for _ in range(num)]))

        self.out_act = nn.Sigmoid() if use_sigmoid else nn.Identity()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.intro(x)
        skips = []
        for encoder, down in zip(self.encoders, self.downs):
            x = encoder(x)
            skips.append(x)
            x = down(x)
        x = self.middle(x)
        for up, decoder in zip(self.ups, self.decoders):
            x = up(x)
            x = x + skips.pop()
            x = decoder(x)
        x = self.ending(x)
        return self.out_act(x)


def _create_zenith_model(base_ch: int = 48, depth: int = 4) -> nn.Module:
    depth = max(1, min(100, depth))
    if depth >= 4:
        base = (2, 4, 6, 8)
        enc  = base + tuple([8] * (depth - 4))
        dec  = tuple([2] * depth)
        mid  = 4
    elif depth == 3:
        enc, dec, mid = (2, 4, 6), (2, 2, 2), 3
    elif depth == 2:
        enc, dec, mid = (2, 4), (2, 2), 2
    else:
        enc, dec, mid = (2,), (2,), 2
    return NAFNetZenith(width=base_ch, enc_blk_nums=enc, dec_blk_nums=dec,
                        middle_blk_num=mid, use_sigmoid=False)


# ============================================================================
# Model architecture — Axiom V3 (Axiom3Model)
# ============================================================================

class GatedConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, padding=1):
        super(GatedConv2d, self).__init__()
        self.conv_gate = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.conv_mask = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.prelu = nn.PReLU(num_parameters=out_channels)

    def forward(self, x):
        gate = self.conv_gate(x)
        mask = torch.sigmoid(self.conv_mask(x))
        return self.prelu(gate * mask)

class Axiom3Model(nn.Module):
    def __init__(self, in_channels=3, out_channels=3):
        super(Axiom3Model, self).__init__()

        # --- ENCODER ---
        self.e1_1 = nn.Sequential(
            nn.Conv2d(in_channels, 16, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=16)
        )
        self.e1_2 = nn.Sequential(
            nn.Conv2d(in_channels + 16, 16, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=16)
        )
        self.e1_3 = nn.Sequential(
            nn.Conv2d(in_channels + 16 + 16, 16, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=16)
        )
        self.e1_4 = GatedConv2d(in_channels + 16 + 16 + 16, 16, kernel_size=3, padding=1)

        self.e2_1 = nn.Sequential(
            nn.Conv2d(64, 32, kernel_size=3, stride=2, padding=1),
            nn.PReLU(num_parameters=32)
        )
        self.e2_2 = nn.Sequential(
            nn.Conv2d(32, 32, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=32)
        )
        self.e2_3 = GatedConv2d(64, 32, kernel_size=3, padding=1)

        self.e4_1 = nn.Sequential(
            nn.Conv2d(96, 64, kernel_size=3, stride=2, padding=1),
            nn.PReLU(num_parameters=64)
        )
        self.e4_2 = GatedConv2d(64, 64, kernel_size=3, padding=1)

        self.e8 = GatedConv2d(128, 128, kernel_size=3, stride=2, padding=1)
        self.e16 = GatedConv2d(128, 192, kernel_size=3, stride=2, padding=1)

        self.e32 = nn.Sequential(
            nn.Conv2d(192, 256, kernel_size=3, stride=2, padding=1),
            nn.PReLU(num_parameters=256)
        )

        self.e64 = nn.Sequential(
            nn.Conv2d(256, 512, kernel_size=3, stride=2, padding=1),
            nn.PReLU(num_parameters=512)
        )

        self.e128 = nn.Sequential(
            nn.Conv2d(512, 512, kernel_size=3, stride=2, padding=1),
            nn.PReLU(num_parameters=512)
        )

        self.e256 = nn.Sequential(
            nn.Conv2d(512, 512, kernel_size=3, stride=2, padding=1),
            nn.PReLU(num_parameters=512)
        )

        # --- BOTTLENECK ---
        self.conv_0 = nn.Sequential(
            nn.Conv2d(512, 256, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=256)
        )

        # --- DECODER ---
        self.conv_1 = nn.Sequential(
            nn.Conv2d(768, 256, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=256)
        )

        self.conv_2 = nn.Sequential(
            nn.Conv2d(768, 256, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=256)
        )

        self.conv_3 = nn.Sequential(
            nn.Conv2d(512, 256, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=256)
        )

        self.conv_4 = nn.Sequential(
            nn.Conv2d(448, 256, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=256)
        )

        self.conv_d4 = nn.Sequential(
            nn.Conv2d(384, 128, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=128)
        )
        self.d4_shuffle = GatedConv2d(128, 512, kernel_size=3, padding=1)
        self.pixel_shuffle_d4 = nn.PixelShuffle(2)

        self.conv_d2 = nn.Sequential(
            nn.Conv2d(256, 128, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=128)
        )
        self.d2_shuffle = GatedConv2d(128, 512, kernel_size=3, padding=1)
        self.pixel_shuffle_d2 = nn.PixelShuffle(2)

        self.conv_d1 = nn.Sequential(
            nn.Conv2d(224, 64, kernel_size=3, padding=1),
            nn.PReLU(num_parameters=64)
        )
        self.d1_shuffle = GatedConv2d(64, 256, kernel_size=3, padding=1)
        self.pixel_shuffle_d1 = nn.PixelShuffle(2)

        self.conv_dd1 = GatedConv2d(128, 48, kernel_size=3, padding=1)
        self.conv_dd2 = GatedConv2d(112, 32, kernel_size=3, padding=1)
        self.conv_stars = nn.Conv2d(144, out_channels, kernel_size=3, padding=1)

    def upsample_2x(self, x):
        return F.interpolate(x, scale_factor=2, mode='nearest')

    def forward(self, x):
        min_val = x.amin(dim=(2, 3), keepdim=True)
        max_val = x.amax(dim=(2, 3), keepdim=True)
        range_val = (max_val - min_val).clamp_min(1e-8)
        x_norm = (x - min_val) / range_val

        # --- Encoder ---
        x1_1 = self.e1_1(x_norm)
        x1_2 = self.e1_2(torch.cat([x_norm, x1_1], dim=1))
        x1_3 = self.e1_3(torch.cat([x_norm, x1_1, x1_2], dim=1))
        x1_4 = self.e1_4(torch.cat([x_norm, x1_1, x1_2, x1_3], dim=1))
        e1_concat = torch.cat([x1_1, x1_2, x1_3, x1_4], dim=1)

        x2_1 = self.e2_1(e1_concat)
        x2_2 = self.e2_2(x2_1)
        x2_3 = self.e2_3(torch.cat([x2_1, x2_2], dim=1))
        e2_concat = torch.cat([x2_1, x2_2, x2_3], dim=1)

        x4_1 = self.e4_1(e2_concat)
        x4_2 = self.e4_2(x4_1)
        e4_concat = torch.cat([x4_1, x4_2], dim=1)

        e8_out = self.e8(e4_concat)
        e16_out = self.e16(e8_out)
        e32_out = self.e32(e16_out)
        e64_out = self.e64(e32_out)
        e128_out = self.e128(e64_out)
        e256_out = self.e256(e128_out)

        # --- Bottleneck ---
        latent = self.conv_0(e256_out)

        # --- Decoder ---
        u_d128 = self.upsample_2x(latent)
        d128_out = self.conv_1(torch.cat([u_d128, e128_out], dim=1))

        u_d64 = self.upsample_2x(d128_out)
        d64_out = self.conv_2(torch.cat([u_d64, e64_out], dim=1))

        u_d32 = self.upsample_2x(d64_out)
        d32_out = self.conv_3(torch.cat([u_d32, e32_out], dim=1))

        u_d16 = self.upsample_2x(d32_out)
        d16_out = self.conv_4(torch.cat([u_d16, e16_out], dim=1))

        u_d8 = self.upsample_2x(d16_out)
        d8_out = self.conv_d4(torch.cat([u_d8, e8_out], dim=1))

        d4_shuffle = self.d4_shuffle(d8_out)
        d4_pixel_shuffle = self.pixel_shuffle_d4(d4_shuffle)

        d2_out = self.conv_d2(torch.cat([d4_pixel_shuffle, e4_concat], dim=1))
        d2_shuffle = self.d2_shuffle(d2_out)
        d2_pixel_shuffle = self.pixel_shuffle_d2(d2_shuffle)

        d1_out = self.conv_d1(torch.cat([d2_pixel_shuffle, e2_concat], dim=1))
        d1_shuffle = self.d1_shuffle(d1_out)
        d1_pixel_shuffle = self.pixel_shuffle_d1(d1_shuffle)

        dd1_out = self.conv_dd1(torch.cat([d1_pixel_shuffle, e1_concat], dim=1))
        dd2_out = self.conv_dd2(torch.cat([d1_pixel_shuffle, dd1_out], dim=1))

        stars_in = torch.cat([d1_pixel_shuffle, dd1_out, dd2_out], dim=1)
        stars_out = self.conv_stars(stars_in)

        starless_norm = x_norm - stars_out
        starless = starless_norm * range_val + min_val
        return torch.clamp(starless, 0.0, 1.0)

def _create_axiom3_model() -> nn.Module:
    return Axiom3Model(in_channels=3, out_channels=3)


# ============================================================================
# Model loading — Zenith
# ============================================================================

def load_zenith_model(
    use_gpu: Optional[bool] = True,
    model_path: Optional[Path] = None,
) -> Tuple[nn.Module, torch.device, bool, bool]:
    """Load and cache the Zenith star-removal model.
    Returns: (model, device, amp_enabled, residual_mode)
    """
    global _ZENITH_MODEL, _ZENITH_DEVICE, _ZENITH_AMP_ENABLED, _ZENITH_RESIDUAL_MODE

    if _ZENITH_MODEL is not None:
        return _ZENITH_MODEL, _ZENITH_DEVICE, _ZENITH_AMP_ENABLED, _ZENITH_RESIDUAL_MODE

    if model_path is None:
        model_path = ZENITH_MODEL_PATH

    if not model_path.exists():
        raise FileNotFoundError(
            f"Zenith model not found at {model_path}. "
            "Please run the script again to trigger automatic download."
        )

    print(f"Loading Zenith model from {model_path}")
    device    = get_device(use_gpu)
    ckpt      = torch.load(model_path, map_location="cpu", weights_only=True)
    ckpt_args = ckpt.get("args", {}) if isinstance(ckpt, dict) else {}
    base_ch   = int(ckpt_args.get("base_ch", 48))
    depth     = int(ckpt_args.get("depth", 4))
    print(f"Zenith config: base_ch={base_ch}, depth={depth}")

    model = _create_zenith_model(base_ch=base_ch, depth=depth).to(device)
    state = ckpt["model"] if isinstance(ckpt, dict) and "model" in ckpt else ckpt
    model.load_state_dict(state)
    model.eval()

    residual_mode = True
    if isinstance(ckpt, dict) and "residual_output" in ckpt:
        residual_mode = bool(ckpt.get("residual_output"))
    print(f"Zenith residual mode: {residual_mode}")

    amp_enabled = device.type in ("cuda", "mps")

    _ZENITH_MODEL         = model
    _ZENITH_DEVICE        = device
    _ZENITH_AMP_ENABLED   = amp_enabled
    _ZENITH_RESIDUAL_MODE = residual_mode

    return model, device, amp_enabled, residual_mode


# ============================================================================
# Model loading — Axiom V3
# ============================================================================

def load_axiom3_model(
    use_gpu: Optional[bool] = True,
    model_path: Optional[Path] = None,
) -> Tuple[nn.Module, torch.device, bool, bool]:
    """Load and cache the Axiom V3 star-removal model.
    Returns: (model, device, amp_enabled, residual_mode)
    """
    global _AXIOM3_MODEL, _AXIOM3_DEVICE, _AXIOM3_AMP_ENABLED, _AXIOM3_RESIDUAL_MODE

    if _AXIOM3_MODEL is not None:
        return _AXIOM3_MODEL, _AXIOM3_DEVICE, _AXIOM3_AMP_ENABLED, _AXIOM3_RESIDUAL_MODE

    if model_path is None:
        model_path = AXIOM3_MODEL_PATH

    if not model_path or not model_path.exists():
        raise FileNotFoundError(
            f"Axiom V3 model not found at {model_path}.\n"
            f"Please place axiom3.pt in: {model_path.parent if model_path else 'the syqon_starless folder'}"
        )

    print(f"Loading Axiom V3 model from {model_path}")
    device    = get_device(use_gpu)
    # Load checkpoint similar to Parallax _load_pth
    try:
        ckpt = torch.load(model_path, map_location="cpu", weights_only=False)
    except TypeError:
        ckpt = torch.load(model_path, map_location="cpu")

    if not isinstance(ckpt, dict):
        if isinstance(ckpt, nn.Module):
            ckpt = {"model_state_dict": ckpt.state_dict()}
        else:
            raise RuntimeError(f"Unrecognized checkpoint format: {type(ckpt)}")

    model = _create_axiom3_model().to(device)

    # State dict cleaning similar to Parallax _clean_state_dict
    sd = ckpt.get("model_state_dict", ckpt.get("model", ckpt))
    cleaned_sd = {}
    for k, v in sd.items():
        name = k
        if name.startswith("_orig_mod."):
            name = name[10:]
        elif name.startswith("module."):
            name = name[7:]
        cleaned_sd[name] = v

    model.load_state_dict(cleaned_sd, strict=True)
    model.eval()

    residual_mode = False
    print(f"Axiom V3 residual mode: {residual_mode}")

    amp_enabled = device.type in ("cuda", "mps")

    _AXIOM3_MODEL         = model
    _AXIOM3_DEVICE        = device
    _AXIOM3_AMP_ENABLED   = amp_enabled
    _AXIOM3_RESIDUAL_MODE = residual_mode

    return model, device, amp_enabled, residual_mode

def _clear_model_caches():
    """Clear all cached models (called when GPU/device toggle changes)."""
    global _ZENITH_MODEL, _ZENITH_DEVICE, _ZENITH_AMP_ENABLED, _ZENITH_RESIDUAL_MODE
    global _AXIOM3_MODEL, _AXIOM3_DEVICE, _AXIOM3_AMP_ENABLED, _AXIOM3_RESIDUAL_MODE
    _ZENITH_MODEL  = None
    _AXIOM3_MODEL = None


# ============================================================================
# Per-channel Inverse Hyperbolic Stretch  (Zenith only)
# ============================================================================

def _to_chw(data: np.ndarray) -> tuple:
    if data.ndim == 2:
        return data[np.newaxis], False
    if data.shape[2] <= 4:
        return data.transpose(2, 0, 1), True
    return data, False


def _to_hwc(chw: np.ndarray, was_hwc: bool, mono: bool) -> np.ndarray:
    if mono:
        return chw[0]
    if was_hwc:
        return chw.transpose(1, 2, 0)
    return chw


def _adaptive_anchor(ch: np.ndarray) -> float:
    stride = max(1, ch.size // 2_000_000)
    sample = ch.flatten()[::stride]
    hist, edges = np.histogram(sample, bins=65536, range=(0.0, 1.0))
    smooth   = np.convolve(hist, np.ones(50) / 50, mode="same")
    peak_idx = int(np.argmax(smooth))
    threshold = smooth[peak_idx] * 0.06
    left  = smooth[:peak_idx]
    cands = np.where(left < threshold)[0]
    anchor = float(edges[cands[-1]]) if len(cands) else float(np.percentile(sample, 0.5))
    return max(0.0, anchor)


def _ihs(x: np.ndarray, D: float, b: float) -> np.ndarray:
    num = np.arcsinh(D * x + b) - np.arcsinh(b)
    den = np.arcsinh(D + b)     - np.arcsinh(b)
    if abs(den) < 1e-12:
        den = 1e-6
    return num / den


def _ihs_inverse(y: np.ndarray, D: float, b: float) -> np.ndarray:
    den = np.arcsinh(D + b) - np.arcsinh(b)
    if abs(den) < 1e-12:
        den = 1e-6
    return (np.sinh(y * den + np.arcsinh(b)) - b) / D


def _solve_log_d(sample: np.ndarray, target: float, b: float) -> float:
    valid = sample[sample > 1e-7]
    if valid.size == 0:
        return 2.0
    med = float(np.median(valid))
    if med < 1e-9:
        return 2.0
    lo, hi, best = 0.0, 7.0, 2.0
    for _ in range(40):
        mid = (lo + hi) / 2.0
        D   = 10.0 ** mid
        val = float(_ihs(np.array([med]), D, b)[0])
        if abs(val - target) < 1e-4:
            best = mid
            break
        if val < target:
            lo = mid
        else:
            hi = mid
    else:
        best = (lo + hi) / 2.0
    return best


def compute_ihs_per_channel_params(
    data: np.ndarray,
    target: float = _IHS_TARGET,
    b: float = _IHS_B,
) -> dict:
    print("Computing IHS pre-stretch parameters...")
    chw, _ = _to_chw(data.astype(np.float32))
    n_channels = chw.shape[0]

    log_ds, anchors = [], []
    for i in range(n_channels):
        ch     = chw[i]
        anchor = _adaptive_anchor(ch)
        ch_anc = np.maximum(ch - anchor, 0.0)
        stride = max(1, ch_anc.size // 100_000)
        sample = ch_anc.flatten()[::stride]
        log_d  = _solve_log_d(sample, target, b)
        log_ds.append(log_d)
        anchors.append(anchor)
        print(f"  ch{i}: anchor={anchor:.6f}, log10(D)={log_d:.4f}")

    return {"log_d": log_ds, "anchor": anchors, "b": b}


def apply_ihs_per_channel(data: np.ndarray, params: dict) -> np.ndarray:
    chw, was_hwc = _to_chw(data.astype(np.float32))
    mono = chw.shape[0] == 1
    b    = params["b"]
    n    = chw.shape[0]

    result = np.empty_like(chw)
    for i in range(n):
        idx    = min(i, len(params["log_d"]) - 1)
        D      = 10.0 ** params["log_d"][idx]
        anchor = params["anchor"][idx]
        ch_anc    = np.maximum(chw[i] - anchor, 0.0)
        result[i] = np.clip(_ihs(ch_anc, D, b), 0.0, 1.0)
        result[i] = np.clip(result[i] * 0.995 + 0.005, 0.0, 1.0)

    return _to_hwc(result, was_hwc, mono)


def apply_ihs_per_channel_inverse(data: np.ndarray, params: dict) -> np.ndarray:
    chw, was_hwc = _to_chw(data.astype(np.float32))
    mono = chw.shape[0] == 1
    b    = params["b"]
    n    = chw.shape[0]

    result = np.empty_like(chw)
    for i in range(n):
        idx    = min(i, len(params["log_d"]) - 1)
        D      = 10.0 ** params["log_d"][idx]
        anchor = params["anchor"][idx]
        ch     = np.clip((chw[i] - 0.005) / 0.995, 0.0, 1.0)
        ch_anc = np.clip(_ihs_inverse(ch, D, b), 0.0, None)
        result[i] = np.clip(ch_anc + anchor, 0.0, 1.0)

    return _to_hwc(result, was_hwc, mono)


# =============================================================================
# Unlinked Statistical Stretch (matches PixInsight Statistical Stretch v2.3 with linkedStretch=OFF)
# =============================================================================

_EPS = 1.0e-12

def _pi_mtf(x: np.ndarray, Med: float, T: float) -> np.ndarray:
    num   = (Med - 1.0) * T * x
    denom = Med * (T + x - 1.0) - T * x
    safe  = np.where(np.abs(denom) < _EPS, _EPS, denom)
    return np.where(np.abs(denom) < _EPS, 0.0, num / safe).astype(np.float32)


def _pi_mtf_inv(y: np.ndarray, Med: float, T: float) -> np.ndarray:
    num   = y * Med * (1.0 - T)
    denom = y * (Med - T) - T * (Med - 1.0)
    safe  = np.where(np.abs(denom) < _EPS, _EPS, denom)
    return np.where(np.abs(denom) < _EPS, 0.0, num / safe).astype(np.float32)


def _compute_channel_params(
    ch: np.ndarray,
    T: float,
    sigma: float,
    no_black_clip: bool,
) -> tuple[float, float, float]:
    Med  = float(np.median(ch))
    Sig  = 1.4826 * float(np.median(np.abs(ch - Med)))
    MinC = float(np.min(ch))

    BPraw = Med - sigma * Sig
    if no_black_clip:
        BP = MinC
    else:
        BP = max(MinC, BPraw)

    scale = 1.0 - BP
    if abs(scale) < _EPS:
        scale = _EPS

    x_bp = np.clip((ch - BP) / scale, 0.0, 1.0)
    Med2 = max(float(np.median(x_bp)), 1e-6)

    return float(BP), float(scale), float(Med2)


def compute_stat_stretch_params(
    img_rgb01: np.ndarray,
    target_median: float = 0.15,
    bp_sigma: float = 5.0,
    no_black_clip: bool = False,
) -> dict[str, Any]:
    x = np.asarray(img_rgb01, dtype=np.float32)

    is_color = (x.ndim == 3 and x.shape[2] == 3)
    if x.ndim == 2:
        x = x[:, :, np.newaxis]
    if x.ndim == 3 and x.shape[2] == 1:
        x = np.repeat(x, 3, axis=2)
        is_color = False

    T     = float(np.clip(target_median, 1e-4, 0.9999))
    sigma = float(bp_sigma)

    channels = []
    for c in range(3):
        BP, scale, Med2 = _compute_channel_params(
            x[..., c], T, sigma, bool(no_black_clip)
        )
        channels.append({
            "BP":    BP,
            "scale": scale,
            "Med2":  Med2,
        })

    return {
        "channels":      channels,
        "target_median": float(T),
        "is_color":      bool(is_color),
        "bp_sigma":      float(sigma),
        "no_black_clip": bool(no_black_clip),
    }


def apply_stat_stretch(
    img_rgb01: np.ndarray,
    params: dict[str, Any],
) -> np.ndarray:
    x        = np.asarray(img_rgb01, dtype=np.float32)
    T        = float(params["target_median"])
    channels = params["channels"]
    out      = np.empty_like(x)

    for c in range(3):
        BP   = float(channels[c]["BP"])
        sc   = float(channels[c]["scale"])
        Med2 = float(channels[c]["Med2"])

        rescaled    = np.clip((x[..., c] - BP) / sc, 0.0, 1.0)
        out[..., c] = np.clip(_pi_mtf(rescaled, Med2, T), 0.0, 1.0)

    return out.astype(np.float32, copy=False)


def invert_stat_stretch(
    img_rgb01: np.ndarray,
    params: dict[str, Any],
) -> np.ndarray:
    y        = np.asarray(img_rgb01, dtype=np.float32)
    T        = float(params["target_median"])
    channels = params["channels"]
    out      = np.empty_like(y)

    for c in range(3):
        BP   = float(channels[c]["BP"])
        sc   = float(channels[c]["scale"])
        Med2 = float(channels[c]["Med2"])

        x_bp        = np.clip(_pi_mtf_inv(y[..., c], Med2, T), 0.0, 1.0)
        out[..., c] = np.clip(x_bp * sc + BP, 0.0, 1.0)

    return out.astype(np.float32, copy=False)


# ============================================================================
# MTF stretch / destretch (from Parallax)
# ============================================================================

def _mtf_apply(x: np.ndarray, s: float, m: float, h: float) -> np.ndarray:
    denom = max(h - s, 1e-8)
    xp = np.clip((x - s) / denom, 0.0, 1.0).astype(np.float32, copy=False)
    num = (m - 1.0) * xp
    den = (2.0 * m - 1.0) * xp - m
    y = np.divide(num, den, out=np.zeros_like(xp), where=np.abs(den) > 1e-12)
    return np.clip(y, 0.0, 1.0).astype(np.float32, copy=False)


def _mtf_inverse(y: np.ndarray, s: float, m: float, h: float) -> np.ndarray:
    yp = np.clip(y.astype(np.float32, copy=False), 0.0, 1.0)
    num = (((s + h) * m - s) * yp - s * m + s)
    den = (2.0 * m - 1.0) * yp - m + 1.0
    x = np.divide(num, den, out=np.full_like(yp, s), where=np.abs(den) > 1e-12)
    return np.clip(x, 0.0, 1.0).astype(np.float32, copy=False)


def _mtf_params_unlinked(img_rgb01: np.ndarray, targetbg: float = 0.20) -> dict:
    """Per-channel MTF params matching stretch_color_image(linked=False, no_black_clip=True)."""
    x = np.asarray(img_rgb01, dtype=np.float32)
    tb = float(np.clip(targetbg, 1e-6, 1.0 - 1e-6))
    s_arr = np.zeros(3, dtype=np.float32)
    m_arr = np.zeros(3, dtype=np.float32)
    for c in range(3):
        ch = x[..., c]
        bp = float(np.clip(ch.min(), 0.0, 1.0 - 1e-6))
        denom = max(1.0 - bp, 1e-12)
        med_rescaled = float(np.clip((float(np.median(ch)) - bp) / denom, 1e-6, 1.0 - 1e-6))
        denom_m = (2.0 * tb - 1.0) * med_rescaled - tb
        if abs(denom_m) < 1e-12:
            denom_m = 1e-12
        m = float(np.clip(med_rescaled * (tb - 1.0) / denom_m, 1e-4, 1.0 - 1e-4))
        s_arr[c] = bp
        m_arr[c] = m
    return {"s": s_arr, "m": m_arr, "h": np.ones(3, dtype=np.float32), "linked": False}


def _mtf_params_linked(img_rgb01: np.ndarray, targetbg: float = 0.20) -> dict:
    """Single blackpoint + avg-channel-median MTF matching stretch_color_image(linked=True, no_black_clip=True)."""
    x = np.asarray(img_rgb01, dtype=np.float32)
    tb = float(np.clip(targetbg, 1e-6, 1.0 - 1e-6))
    bp = float(np.clip(x.min(), 0.0, 1.0 - 1e-6))
    denom = max(1.0 - bp, 1e-12)
    om0 = float(np.median(np.clip((x[..., 0] - bp) / denom, 0.0, 1.0)))
    om1 = float(np.median(np.clip((x[..., 1] - bp) / denom, 0.0, 1.0)))
    om2 = float(np.median(np.clip((x[..., 2] - bp) / denom, 0.0, 1.0)))
    med_rescaled = float(np.clip((om0 + om1 + om2) / 3.0, 1e-6, 1.0 - 1e-6))
    denom_m = (2.0 * tb - 1.0) * med_rescaled - tb
    if abs(denom_m) < 1e-12:
        denom_m = 1e-12
    m = float(np.clip(med_rescaled * (tb - 1.0) / denom_m, 1e-4, 1.0 - 1e-4))
    return {"s": bp, "m": m, "h": 1.0, "linked": True}


def apply_mtf_stretch(img_rgb01: np.ndarray, params: dict) -> np.ndarray:
    x = np.asarray(img_rgb01, dtype=np.float32)
    out = np.empty_like(x)
    if params["linked"]:
        s, m, h = float(params["s"]), float(params["m"]), float(params["h"])
        for c in range(3):
            out[..., c] = _mtf_apply(x[..., c], s, m, h)
    else:
        for c in range(3):
            out[..., c] = _mtf_apply(x[..., c],
                                      float(params["s"][c]),
                                      float(params["m"][c]),
                                      float(params["h"][c]))
    return np.clip(out, 0.0, 1.0).astype(np.float32, copy=False)


def apply_mtf_inverse(img_rgb01: np.ndarray, params: dict) -> np.ndarray:
    y = np.asarray(img_rgb01, dtype=np.float32)
    out = np.empty_like(y)
    if params["linked"]:
        s, m, h = float(params["s"]), float(params["m"]), float(params["h"])
        for c in range(3):
            out[..., c] = _mtf_inverse(y[..., c], s, m, h)
    else:
        for c in range(3):
            out[..., c] = _mtf_inverse(y[..., c],
                                        float(params["s"][c]),
                                        float(params["m"][c]),
                                        float(params["h"][c]))
    return np.clip(out, 0.0, 1.0).astype(np.float32, copy=False)


def _make_safe_header(raw_header: str, new_filter: str) -> str:
    if not raw_header:
        return ""
    try:
        lines = raw_header.split("\n")
        lines = [l for l in lines if not (l.strip().startswith("END") or
                                           l.strip().startswith("CONTINUE") or
                                           l.strip().endswith("&'"))]
        while lines and not lines[-1].strip():
            lines.pop()
        header_dict = fits.Header.fromstring("\n".join(lines), sep="\n")
        header_dict["FILTER"] = new_filter
        header_dict.remove("BG-PTS", ignore_missing=True)
        header_dict.verify("silentfix")
        return header_dict.tostring(sep="\n")
    except Exception as e:
        print(f"Warning: safe FITS header creation failed for filter '{new_filter}': {e}. Using raw header.")
        return raw_header


def _image_stats(label: str, data: np.ndarray):
    arr = np.asarray(data, dtype=np.float32)
    arr = arr[np.isfinite(arr)]
    if arr.size == 0:
        print(f"{label}: no finite pixels")
        return
    print(
        f"{label}: min={float(np.min(arr)):.6f}, "
        f"median={float(np.median(arr)):.6f}, max={float(np.max(arr)):.6f}"
    )


# ============================================================================
# Tiling helpers
# ============================================================================

def _weight_1d(size: int, overlap: int, device: torch.device, dtype: torch.dtype) -> torch.Tensor:
    if overlap <= 0:
        return torch.ones(size, device=device, dtype=dtype)
    # Cosine ramp (Hann window edge) for smoother blending in overlap regions
    ramp         = 0.5 - 0.5 * torch.cos(torch.linspace(0.0, np.pi, overlap, device=device, dtype=dtype))
    w            = torch.ones(size, device=device, dtype=dtype)
    w[:overlap]  = ramp
    w[-overlap:] = torch.flip(ramp, dims=[0])
    return w


def _edge_key(pos: int, size: int, tile: int) -> str:
    if pos == 0:
        return "top"
    if pos + tile >= size:
        return "bot"
    return "mid"


def _build_weight_cache(tile_size: int, overlap: int, device: torch.device, dtype: torch.dtype) -> dict:
    def axis_weights(size, overlap, device, dtype):
        base = _weight_1d(size, overlap, device, dtype)
        top  = base.clone()
        bot  = base.clone()
        if overlap > 0:
            top[:overlap]  = 1.0
            bot[-overlap:] = 1.0
        return top, base, bot

    wy_top, wy_mid, wy_bot    = axis_weights(tile_size, overlap, device, dtype)
    wx_left, wx_mid, wx_right = axis_weights(tile_size, overlap, device, dtype)

    cache = {}
    for yk, wy in (("top", wy_top), ("mid", wy_mid), ("bot", wy_bot)):
        for xk, wx in (("left", wx_left), ("mid", wx_mid), ("right", wx_right)):
            cache[(yk, xk)] = (wy[:, None] * wx[None, :]).unsqueeze(0).unsqueeze(0)
    return cache


def _tile_positions(size: int, tile_size: int, stride: int) -> list:
    if size <= tile_size:
        return [0]
    pos = list(range(0, size - tile_size, stride))
    if pos[-1] != size - tile_size:
        pos.append(size - tile_size)
    return pos


def tile_inference_torch(
    model: nn.Module,
    x: torch.Tensor,
    tile_size: int,
    overlap: int,
    device: torch.device,
    amp_enabled: bool,
    progress_callback: Optional[Callable[[int], None]] = None,
    progress_start: int = 10,
    progress_range: int = 75,
    tile_callback: Optional[Callable[[int, int, int, int, np.ndarray], None]] = None,
    tile_transform: Optional[Callable[[torch.Tensor, torch.Tensor], np.ndarray]] = None,
    check_cancel: Optional[Callable[[], bool]] = None,
) -> torch.Tensor:
    _, _, h, w = x.shape

    if tile_size <= 0 or tile_size >= min(h, w):
        if progress_callback:
            progress_callback(progress_start + progress_range // 2)
        with torch.no_grad(), amp.autocast(device_type=device.type, enabled=amp_enabled):
            result = model(x)
        if progress_callback:
            progress_callback(progress_start + progress_range)
        return result

    stride = tile_size - overlap
    if stride <= 0:
        raise ValueError("overlap must be smaller than tile_size")

    ys = _tile_positions(h, tile_size, stride)
    xs = _tile_positions(w, tile_size, stride)
    total_tiles = len(ys) * len(xs)

    out    = torch.zeros_like(x, device=device)
    weight = torch.zeros((1, 1, h, w), device=device, dtype=x.dtype)
    cache  = _build_weight_cache(tile_size, overlap, device, x.dtype)
    xk_map = {"top": "left", "mid": "mid", "bot": "right"}

    tile_count = 0
    with torch.no_grad():
        for y in reversed(ys):
            yk = _edge_key(y, h, tile_size)
            for x0 in xs:
                if check_cancel is not None and check_cancel():
                    raise InterruptedError("Cancelled")
                xk  = xk_map[_edge_key(x0, w, tile_size)]
                w2  = cache[(yk, xk)]
                tile = x[:, :, y : y + tile_size, x0 : x0 + tile_size]
                try:
                    with amp.autocast(device_type=device.type, enabled=amp_enabled):
                        pred = model(tile)
                except Exception:
                    pred = model(tile)

                out   [:, :, y : y + tile_size, x0 : x0 + tile_size] += pred * w2
                weight[:, :, y : y + tile_size, x0 : x0 + tile_size] += w2

                if tile_callback is not None:
                    if tile_transform is not None:
                        patch = tile_transform(tile, pred)
                    else:
                        patch = pred[0].clamp(0, 1).permute(1, 2, 0).cpu().numpy().astype(np.float32)
                    tile_callback(y, x0, pred.shape[2], pred.shape[3], patch)

                tile_count += 1
                if progress_callback:
                    pct = progress_start + int((tile_count / total_tiles) * progress_range)
                    progress_callback(pct)

    return out / weight.clamp(min=1e-8)
# ============================================================================
# Star mask generation
# ============================================================================

def generate_star_mask(
    original: np.ndarray,
    starless: np.ndarray,
    method: str = "subtraction",
) -> np.ndarray:
    if method == "subtraction":
        mask = np.clip(original - starless, 0, None)
    else:
        epsilon = 1e-8
        ratio   = original / (starless + epsilon)
        mask    = original * (1.0 - 1.0 / (ratio + epsilon))
        mask    = np.clip(mask, 0, None)
    return mask.astype(original.dtype)


# ============================================================================
# High-level processing function
# ============================================================================

def process_image(
    img: np.ndarray,
    tile: int = 368,
    overlap: int = 64,
    generate_mask: bool = True,
    mask_method: str = "subtraction",
    use_amp: bool = True,
    use_gpu: Optional[bool] = True,
    model_path: Optional[Path] = None,
    model_type: str = "zenith",
    progress_callback: Optional[Callable[[int], None]] = None,
    tile_callback: Optional[Callable[[int, int, int, int, np.ndarray], None]] = None,
    ihs_target: float = 0.15,
    check_cancel: Optional[Callable[[], bool]] = None,
    stretch_method: str = "statistical",
    mtf_target: float = 0.15,
    linked_stretch: bool = False,
) -> Tuple[np.ndarray, Optional[np.ndarray]]:
    """
    Remove stars from a single image.
    """
    def _emit(v: int):
        if progress_callback:
            progress_callback(v)

    _emit(0)

    # ---- detect and normalise layout -----------------------------------------
    is_planar = False
    is_mono   = False

    if img.ndim == 3 and img.shape[0] in (1, 3, 4):
        if img.shape[0] < min(img.shape[1], img.shape[2]):
            is_planar = True
            is_mono   = img.shape[0] == 1

    if is_planar:
        img = np.transpose(img, (1, 2, 0))   # (C,H,W) -> (H,W,C)

    if img.ndim == 2:
        is_mono = True
        img = img[..., None]                  # (H,W) -> (H,W,1)

    original = img.copy() if generate_mask else None

    if img.shape[2] == 1:
        is_mono = True
        img_for_stretch = np.repeat(img, 3, axis=2)
    elif img.shape[2] == 4:
        img_for_stretch = img[:, :, :3]
    else:
        img_for_stretch = img

    # ---- stretch pre-processing ----------------------------------------------
    stretched_params = None
    if stretch_method == "ihs":
        print("Computing IHS pre-stretch parameters...")
        ihs_params = compute_ihs_per_channel_params(img_for_stretch, target=ihs_target)
        img_for_model = apply_ihs_per_channel(img_for_stretch, ihs_params)
        stretched_params = {"type": "ihs", "params": ihs_params}
    elif stretch_method == "mtf":
        print("Computing MTF pre-stretch parameters...")
        mtf_params = (_mtf_params_linked(img_for_stretch, targetbg=mtf_target)
                      if linked_stretch
                      else _mtf_params_unlinked(img_for_stretch, targetbg=mtf_target))
        img_for_model = apply_mtf_stretch(img_for_stretch, mtf_params)
        stretched_params = {"type": "mtf", "params": mtf_params}
    elif stretch_method == "statistical":
        print("Computing Statistical Stretch parameters...")
        stat_params = compute_stat_stretch_params(img_for_stretch, target_median=mtf_target)
        img_for_model = apply_stat_stretch(img_for_stretch, stat_params)
        stretched_params = {"type": "statistical", "params": stat_params}
    else:
        img_for_model = img_for_stretch
        stretched_params = {"type": "none"}

    # ---- model-specific loading ----------------------------------------------
    _emit(5)
    if model_type == "axiom3":
        model, device, amp_enabled, residual_mode = load_axiom3_model(use_gpu=use_gpu, model_path=model_path)
        print(f">>> [Axiom V3] residual_mode={residual_mode} (direct starless if False)")
    else:
        model, device, amp_enabled, residual_mode = load_zenith_model(use_gpu=use_gpu, model_path=model_path)

    amp_enabled = use_amp and amp_enabled
    if amp_enabled:
        print("Automatic Mixed Precision (AMP) enabled")

    # ---- to tensor -----------------------------------------------------------
    print("Inferencing...")
    x = (
        torch.from_numpy(img_for_model.astype(np.float32))
        .permute(2, 0, 1)
        .unsqueeze(0)
        .to(device)
    )
    _emit(10)

    def tile_transform_fn(inp_t, pred_t):
        raw_tile = ((inp_t - pred_t) if residual_mode else pred_t).squeeze(0).clamp(0, 1).permute(1, 2, 0).cpu().numpy().astype(np.float32)
        if stretched_params["type"] == "ihs":
            return apply_ihs_per_channel_inverse(raw_tile, stretched_params["params"])
        elif stretched_params["type"] == "mtf":
            return apply_mtf_inverse(raw_tile, stretched_params["params"])
        elif stretched_params["type"] == "statistical":
            return invert_stat_stretch(raw_tile, stretched_params["params"])
        return raw_tile

    pred = tile_inference_torch(
        model, x, tile, overlap, device, amp_enabled,
        progress_callback=progress_callback,
        progress_start=10,
        progress_range=75,
        tile_callback=tile_callback,
        tile_transform=tile_transform_fn,
        check_cancel=check_cancel,
    )
    _emit(87)

    # ---- apply residual mode -------------------------------------------------
    if residual_mode:
        pred = x - pred

    # ---- back to numpy -------------------------------------------------------
    result_stretched = pred.squeeze(0).clamp(0, 1).permute(1, 2, 0).cpu().numpy()
    _image_stats("Model output", result_stretched)

    # ---- invert stretch ------------------------------------------------------
    if stretched_params["type"] == "ihs":
        result = apply_ihs_per_channel_inverse(result_stretched, stretched_params["params"])
    elif stretched_params["type"] == "mtf":
        result = apply_mtf_inverse(result_stretched, stretched_params["params"])
    elif stretched_params["type"] == "statistical":
        result = invert_stat_stretch(result_stretched, stretched_params["params"])
    else:
        result = result_stretched
    _image_stats("Linear output", result)

    # ---- star mask -----------------------------------------------------------
    star_mask = None
    if generate_mask and original is not None:
        _emit(90)
        orig_for_mask = original
        if orig_for_mask.ndim == 2:
            orig_for_mask = np.repeat(orig_for_mask[..., None], 3, axis=2)
        elif orig_for_mask.shape[2] == 1:
            orig_for_mask = np.repeat(orig_for_mask, 3, axis=2)
        elif orig_for_mask.shape[2] == 4:
            orig_for_mask = orig_for_mask[:, :, :3]
        star_mask = generate_star_mask(orig_for_mask, result, mask_method)

    # ---- restore original layout --------------------------------------------
    print(f"Mono: {is_mono}, planar: {is_planar}")

    if is_mono:
        result = np.mean(result, axis=2, keepdims=True)
        if star_mask is not None:
            star_mask = np.mean(star_mask, axis=2, keepdims=True)

    if is_planar:
        result = np.transpose(result, (2, 0, 1))
        if star_mask is not None:
            star_mask = np.transpose(star_mask, (2, 0, 1))

    if is_mono and not is_planar:
        result = result.squeeze(-1)
        if star_mask is not None:
            star_mask = star_mask.squeeze(-1)

    _emit(100)
    return result, star_mask


# ============================================================================
# Programmatic (non-blocking) interface
# ============================================================================

class InferenceEngine:
    """Non-blocking inference engine for programmatic use."""

    def __init__(self, use_gpu: bool = True, model: str = "zenith"):
        self._thread: Optional[Thread] = None
        self.use_gpu    = use_gpu
        self.model_type = model  # "zenith" or "axiom3"
        if model == "axiom3":
            self.model_path = AXIOM3_MODEL_PATH
        else:
            self.model_path = ZENITH_MODEL_PATH
        print_logo()

    def process_async(
        self,
        image: np.ndarray,
        tile_size: int = 368,
        overlap: int = 64,
        generate_mask: bool = True,
        mask_method: str = "subtraction",
        use_amp: bool = True,
        callback: Optional[Callable] = None,
        error_callback: Optional[Callable] = None,
    ) -> None:
        model_path  = self.model_path
        model_type  = self.model_type

        def _run():
            try:
                starless, mask = process_image(
                    image,
                    tile=tile_size,
                    overlap=overlap,
                    generate_mask=generate_mask,
                    mask_method=mask_method,
                    use_amp=use_amp,
                    use_gpu=self.use_gpu,
                    model_path=model_path,
                    model_type=model_type,
                )
                if callback:
                    callback((starless, mask))
            except Exception as exc:
                if error_callback:
                    error_callback(str(exc))

        self._thread = Thread(target=_run, daemon=True)
        self._thread.start()

    def is_processing(self) -> bool:
        return self._thread is not None and self._thread.is_alive()


# ============================================================================
# Qt worker
# ============================================================================

class ProcessingWorker(QObject):
    finished = Signal(tuple)
    error    = Signal(str)
    progress = Signal(int)
    tile_preview = Signal(int, int, int, int, object)

    def __init__(
        self,
        image: np.ndarray,
        tile_size: int,
        overlap: int,
        generate_mask: bool,
        mask_method: str,
        use_amp: bool,
        use_gpu: bool,
        model_path: Path,
        model_type: str = "zenith",
        ihs_target: float = 0.15,
        frame_index: int = 0,
        frame_obj: Any = None,
        stretch_method: str = "statistical",
        mtf_target: float = 0.15,
        linked_stretch: bool = False,
    ):
        super().__init__()
        self.image         = image
        self.tile_size     = tile_size
        self.overlap       = overlap
        self.generate_mask = generate_mask
        self.mask_method   = mask_method
        self.use_amp       = use_amp
        self.use_gpu       = use_gpu
        self.model_path    = model_path
        self.model_type    = model_type
        self.ihs_target    = ihs_target
        self.frame_index   = frame_index
        self.frame_obj     = frame_obj
        self.stretch_method = stretch_method
        self.mtf_target     = mtf_target
        self.linked_stretch = linked_stretch
        self._cancel        = False

    def cancel(self):
        self._cancel = True

    def is_cancelled(self) -> bool:
        return self._cancel

    def run(self):
        try:
            starless, mask = process_image(
                self.image,
                tile=self.tile_size,
                overlap=self.overlap,
                generate_mask=self.generate_mask,
                mask_method=self.mask_method,
                use_amp=self.use_amp,
                use_gpu=self.use_gpu,
                model_path=self.model_path,
                model_type=self.model_type,
                progress_callback=self.progress.emit,
                tile_callback=lambda y, x, h, w, p: self.tile_preview.emit(y, x, h, w, p),
                ihs_target=self.ihs_target,
                check_cancel=self.is_cancelled,
                stretch_method=self.stretch_method,
                mtf_target=self.mtf_target,
                linked_stretch=self.linked_stretch,
            )
            self.finished.emit((starless, mask, self.frame_index, self.frame_obj))
        except InterruptedError:
            self.error.emit("__cancelled__")
        except Exception as exc:
            import traceback
            traceback.print_exc()
            self.error.emit(f"{type(exc).__name__}: {exc}")


def _to_preview_rgb(data: np.ndarray) -> np.ndarray:
    arr = np.asarray(data, dtype=np.float32)
    if arr.ndim == 3 and arr.shape[0] in (1, 3, 4) and arr.shape[0] < min(arr.shape[1], arr.shape[2]):
        arr = arr.transpose(1, 2, 0)
    if arr.ndim == 2:
        arr = np.stack([arr] * 3, axis=-1)
    elif arr.ndim == 3 and arr.shape[2] == 1:
        arr = np.repeat(arr, 3, axis=2)
    elif arr.ndim == 3 and arr.shape[2] >= 3:
        arr = arr[:, :, :3]
    arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
    return np.clip(arr, 0.0, 1.0).astype(np.float32)


def _rgb_to_qimage(rgb: np.ndarray) -> QImage:
    rgb8 = np.ascontiguousarray((np.clip(rgb, 0, 1) * 255.0).astype(np.uint8))
    h, w = rgb8.shape[:2]
    qimg = QImage(rgb8.data, w, h, w * 3, QImage.Format.Format_RGB888).copy()
    return qimg.flipped(Qt.Vertical)


def _rgb_to_qimage_with_alpha(rgb: np.ndarray, alpha: np.ndarray) -> QImage:
    h, w = rgb.shape[:2]
    rgba = np.empty((h, w, 4), dtype=np.uint8)
    rgba[..., :3] = (np.clip(rgb, 0, 1) * 255.0).astype(np.uint8)
    rgba[..., 3]  = (np.clip(alpha, 0, 1) * 255.0).astype(np.uint8)
    qimg = QImage(rgba.data, w, h, w * 4, QImage.Format.Format_RGBA8888).copy()
    return qimg.flipped(Qt.Vertical)


class BeforeAfterPreview(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.img_before = None # QImage
        self.img_after = None  # QImage
        self.split_ratio = 0.5 # 0.0 to 1.0
        self.zoom_factor = 1.0 # 1.0 to 10.0
        self.pan_offset = QPoint(0, 0)
        self.dragging_split = False
        self.dragging_pan = False
        self.last_mouse_pos = None
        self.show_split = True
        self.accum_out = None
        self.accum_weight = None
        self.preview_mode = "starless"
        
        # ROI selection variables
        self.roi_rect = None # QRect in image coordinates
        self.is_selecting_roi = False
        self.roi_start = None # QPoint in widget coordinates
        self.roi_end = None # QPoint in widget coordinates
        self.roi_changed_cb = None
        
        # ROI dragging variables
        self.dragging_roi = False
        self.roi_drag_start_rect = None
        self.roi_drag_start_img_pos = None
        
        self.setMouseTracking(True)
        self.setCursor(Qt.CursorShape.ArrowCursor)

    def set_images(self, before: QImage, after: QImage = None, reset_zoom: bool = False):
        dimensions_changed = True
        if self.img_before and before:
            if self.img_before.width() == before.width() and self.img_before.height() == before.height():
                dimensions_changed = False
        
        self.img_before = before
        self.img_after = after
        
        if reset_zoom or dimensions_changed:
            self.zoom_factor = 1.0
            self.pan_offset = QPoint(0, 0)
            self.roi_rect = None
            if self.roi_changed_cb:
                self.roi_changed_cb()
        self.update()

    def set_before(self, img: np.ndarray):
        before_q = _rgb_to_qimage(img)
        self.set_images(before_q, self.img_after, reset_zoom=False)

    def set_after(self, img: np.ndarray):
        after_q = _rgb_to_qimage(img)
        self.set_images(self.img_before, after_q, reset_zoom=False)

    def set_zoom_fit(self):
        self.zoom_factor = 1.0
        self.pan_offset = QPoint(0, 0)
        self.update()

    def set_zoom_100(self):
        if not self.img_before:
            return
        w = self.width()
        h = self.height()
        img_w = self.img_before.width()
        img_h = self.img_before.height()
        scale = min(w / img_w, h / img_h)
        if scale > 0:
            self.zoom_factor = max(1.0, 1.0 / scale)
        else:
            self.zoom_factor = 1.0
        self.pan_offset = QPoint(0, 0)
        self.update()

    def set_zoom_200(self):
        if not self.img_before:
            return
        w = self.width()
        h = self.height()
        img_w = self.img_before.width()
        img_h = self.img_before.height()
        scale = min(w / img_w, h / img_h)
        if scale > 0:
            self.zoom_factor = max(1.0, 2.0 / scale)
        else:
            self.zoom_factor = 2.0
        self.pan_offset = QPoint(0, 0)
        self.update()

    def widget_to_image_coords(self, point: QPoint) -> QPoint:
        if not self.img_before:
            return QPoint(0, 0)
        w = self.width()
        h = self.height()
        img_w = self.img_before.width()
        img_h = self.img_before.height()
        scale = min(w / img_w, h / img_h)
        draw_w = int(img_w * scale)
        draw_h = int(img_h * scale)
        zw = int(draw_w * self.zoom_factor)
        zh = int(draw_h * self.zoom_factor)
        zdx = (w - zw) // 2
        zdy = (h - zh) // 2
        
        if self.zoom_factor > 1.0:
            max_pan_x = max(0, (zw - w) // 2 + 50)
            max_pan_y = max(0, (zh - h) // 2 + 50)
            px = max(-max_pan_x, min(max_pan_x, self.pan_offset.x()))
            py = max(-max_pan_y, min(max_pan_y, self.pan_offset.y()))
        else:
            px, py = 0, 0
            
        final_x = zdx + px
        final_y = zdy + py
        
        x_img = int((point.x() - final_x) * img_w / zw)
        y_img = int((point.y() - final_y) * img_h / zh)
        
        x_img = max(0, min(img_w - 1, x_img))
        y_img = img_h - 1 - max(0, min(img_h - 1, y_img))
        return QPoint(x_img, y_img)

    def image_to_widget_coords(self, point: QPoint) -> QPoint:
        if not self.img_before:
            return QPoint(0, 0)
        w = self.width()
        h = self.height()
        img_w = self.img_before.width()
        img_h = self.img_before.height()
        scale = min(w / img_w, h / img_h)
        draw_w = int(img_w * scale)
        draw_h = int(img_h * scale)
        zw = int(draw_w * self.zoom_factor)
        zh = int(draw_h * self.zoom_factor)
        zdx = (w - zw) // 2
        zdy = (h - zh) // 2
        
        if self.zoom_factor > 1.0:
            max_pan_x = max(0, (zw - w) // 2 + 50)
            max_pan_y = max(0, (zh - h) // 2 + 50)
            px = max(-max_pan_x, min(max_pan_x, self.pan_offset.x()))
            py = max(-max_pan_y, min(max_pan_y, self.pan_offset.y()))
        else:
            px, py = 0, 0
            
        final_x = zdx + px
        final_y = zdy + py
        
        x_widget = int(final_x + point.x() * zw / img_w)
        y_widget = int(final_y + (img_h - 1 - point.y()) * zh / img_h)
        return QPoint(x_widget, y_widget)

    def wheelEvent(self, event):
        if not self.img_before:
            return
        angle = event.angleDelta().y()
        old_zoom = self.zoom_factor
        if angle > 0:
            self.zoom_factor = min(10.0, self.zoom_factor * 1.15)
        else:
            self.zoom_factor = max(1.0, self.zoom_factor / 1.15)
        
        if self.zoom_factor == 1.0:
            self.pan_offset = QPoint(0, 0)
        else:
            w = self.width()
            h = self.height()
            widget_center = QPoint(w // 2, h // 2)
            mouse_pos = event.position().toPoint()
            delta_mouse = mouse_pos - widget_center
            self.pan_offset = delta_mouse - (delta_mouse - self.pan_offset) * (self.zoom_factor / old_zoom)
        self.update()

    def mouseDoubleClickEvent(self, event):
        if not self.img_before:
            return
        if event.button() == Qt.MouseButton.LeftButton:
            if self.zoom_factor > 1.0:
                self.zoom_factor = 1.0
                self.pan_offset = QPoint(0, 0)
            else:
                old_zoom = 1.0
                self.zoom_factor = 3.0
                w = self.width()
                h = self.height()
                widget_center = QPoint(w // 2, h // 2)
                mouse_pos = event.position().toPoint()
                delta_mouse = mouse_pos - widget_center
                self.pan_offset = delta_mouse - (delta_mouse - self.pan_offset) * (self.zoom_factor / old_zoom)
            self.update()

    def mousePressEvent(self, event):
        if not self.img_before:
            return
        if event.button() == Qt.MouseButton.LeftButton:
            w = self.width()
            line_x = self.split_ratio * w
            if getattr(self, "show_split", True) and abs(event.position().x() - line_x) < 20:
                self.dragging_split = True
            else:
                p_img = self.widget_to_image_coords(event.position().toPoint())
                if self.roi_rect and self.roi_rect.contains(p_img):
                    self.dragging_roi = True
                    self.roi_drag_start_rect = QRect(self.roi_rect)
                    self.roi_drag_start_img_pos = p_img
                    self.setCursor(Qt.CursorShape.SizeAllCursor)
                else:
                    self.dragging_pan = True
                    self.last_mouse_pos = event.position()
                    if self.zoom_factor > 1.0:
                        self.setCursor(Qt.CursorShape.ClosedHandCursor)
        elif event.button() == Qt.MouseButton.RightButton:
            self.is_selecting_roi = True
            self.roi_start = event.position().toPoint()
            self.roi_end = event.position().toPoint()
            self.setCursor(Qt.CursorShape.CrossCursor)

    def mouseMoveEvent(self, event):
        if not self.img_before:
            return
        w = self.width()
        line_x = self.split_ratio * w
        
        if self.dragging_split:
            self.split_ratio = max(0.0, min(1.0, event.position().x() / w))
            self.update()
        elif self.dragging_roi:
            p_img = self.widget_to_image_coords(event.position().toPoint())
            delta = p_img - self.roi_drag_start_img_pos
            
            img_w = self.img_before.width()
            img_h = self.img_before.height()
            
            new_x = self.roi_drag_start_rect.x() + delta.x()
            new_y = self.roi_drag_start_rect.y() + delta.y()
            
            new_x = max(0, min(img_w - self.roi_drag_start_rect.width(), new_x))
            new_y = max(0, min(img_h - self.roi_drag_start_rect.height(), new_y))
            
            self.roi_rect.moveTo(new_x, new_y)
            self.update()
            if self.roi_changed_cb:
                self.roi_changed_cb()
        elif self.dragging_pan:
            delta = event.position() - self.last_mouse_pos
            self.pan_offset += QPoint(int(delta.x()), int(delta.y()))
            self.last_mouse_pos = event.position()
            self.update()
        elif self.is_selecting_roi:
            self.roi_end = event.position().toPoint()
            self.update()
        else:
            if getattr(self, "show_split", True) and abs(event.position().x() - line_x) < 15:
                self.setCursor(Qt.CursorShape.SplitHCursor)
            else:
                p_img = self.widget_to_image_coords(event.position().toPoint())
                if self.roi_rect and self.roi_rect.contains(p_img):
                    self.setCursor(Qt.CursorShape.SizeAllCursor)
                elif self.zoom_factor > 1.0:
                    self.setCursor(Qt.CursorShape.OpenHandCursor)
                else:
                    self.setCursor(Qt.CursorShape.ArrowCursor)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.dragging_split = False
            self.dragging_pan = False
            self.dragging_roi = False
            self.roi_drag_start_rect = None
            self.roi_drag_start_img_pos = None
            
            w = self.width()
            line_x = self.split_ratio * w
            if getattr(self, "show_split", True) and abs(event.position().x() - line_x) < 15:
                self.setCursor(Qt.CursorShape.SplitHCursor)
            else:
                p_img = self.widget_to_image_coords(event.position().toPoint())
                if self.roi_rect and self.roi_rect.contains(p_img):
                    self.setCursor(Qt.CursorShape.SizeAllCursor)
                elif self.zoom_factor > 1.0:
                    self.setCursor(Qt.CursorShape.OpenHandCursor)
                else:
                    self.setCursor(Qt.CursorShape.ArrowCursor)
        elif event.button() == Qt.MouseButton.RightButton and self.is_selecting_roi:
            self.is_selecting_roi = False
            self.setCursor(Qt.CursorShape.ArrowCursor)
            
            p1 = self.widget_to_image_coords(self.roi_start)
            p2 = self.widget_to_image_coords(self.roi_end)
            
            x = min(p1.x(), p2.x())
            y = min(p1.y(), p2.y())
            rw = abs(p1.x() - p2.x())
            rh = abs(p1.y() - p2.y())
            
            if rw > 10 and rh > 10:
                self.roi_rect = QRect(x, y, rw, rh)
            else:
                self.roi_rect = None
            
            self.update()
            if self.roi_changed_cb:
                self.roi_changed_cb()

    def paintEvent(self, event):
        painter = QPainter(self)
        w = self.width()
        h = self.height()
        if w <= 0 or h <= 0:
            return

        if not self.img_before:
            painter.fillRect(self.rect(), QColor("#121212"))
            painter.setPen(QPen(QColor("#8e8e93")))
            painter.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, "No Preview Image")
            return

        img_w = self.img_before.width()
        img_h = self.img_before.height()
        scale = min(w / img_w, h / img_h)
        draw_w = int(img_w * scale)
        draw_h = int(img_h * scale)

        zw = int(draw_w * self.zoom_factor)
        zh = int(draw_h * self.zoom_factor)

        zdx = (w - zw) // 2
        zdy = (h - zh) // 2

        if self.zoom_factor > 1.0:
            max_pan_x = max(0, (zw - w) // 2 + 50)
            max_pan_y = max(0, (zh - h) // 2 + 50)
            px = max(-max_pan_x, min(max_pan_x, self.pan_offset.x()))
            py = max(-max_pan_y, min(max_pan_y, self.pan_offset.y()))
            self.pan_offset.setX(px)
            self.pan_offset.setY(py)
        else:
            self.pan_offset = QPoint(0, 0)

        final_x = zdx + self.pan_offset.x()
        final_y = zdy + self.pan_offset.y()

        painter.fillRect(self.rect(), QColor("#121212"))
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)

        if not self.img_after or not getattr(self, "show_split", True):
            img_to_draw = self.img_after if self.img_after else self.img_before
            painter.drawImage(QRect(final_x, final_y, zw, zh), img_to_draw)
        else:
            split_x = int(self.split_ratio * w)

            painter.save()
            painter.setClipRect(QRect(0, 0, split_x, h))
            painter.drawImage(QRect(final_x, final_y, zw, zh), self.img_before)
            painter.restore()

            painter.save()
            painter.setClipRect(QRect(split_x, 0, w, h))
            painter.drawImage(QRect(final_x, final_y, zw, zh), self.img_after)
            painter.restore()

            # Draw modern split line with a subtle accent color glow
            pen = QPen(QColor(59, 130, 246, 180), 2)
            painter.setPen(pen)
            painter.drawLine(split_x, 0, split_x, h)

            # Draw glassy split handle
            circle_r = 15
            cy = h // 2
            
            # Outer glow/shadow
            painter.setBrush(QBrush(QColor(255, 255, 255, 20)))
            painter.setPen(Qt.PenStyle.NoPen)
            painter.drawEllipse(split_x - circle_r - 2, cy - circle_r - 2, (circle_r + 2) * 2, (circle_r + 2) * 2)
            
            # Handle background
            painter.setBrush(QBrush(QColor("#161a22")))
            painter.setPen(QPen(QColor(59, 130, 246), 2))
            painter.drawEllipse(split_x - circle_r, cy - circle_r, circle_r * 2, circle_r * 2)

            # Modern glyphs
            painter.setPen(QPen(QColor("#ffffff"), 2))
            painter.drawLine(split_x - 5, cy, split_x - 2, cy - 3)
            painter.drawLine(split_x - 5, cy, split_x - 2, cy + 3)
            painter.drawLine(split_x + 5, cy, split_x + 2, cy - 3)
            painter.drawLine(split_x + 5, cy, split_x + 2, cy + 3)

        # Draw floating labels: ORIGINAL / RESULT
        if self.img_before:
            painter.save()
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            font = QFont("SF Pro Display", 9, QFont.Weight.Bold)
            painter.setFont(font)
            fm = painter.fontMetrics()
            
            # ORIGINAL (bottom left side)
            orig_text = "ORIGINAL"
            orig_w = fm.horizontalAdvance(orig_text) + 16
            orig_h = fm.height() + 8
            orig_rect = QRect(12, h - orig_h - 12, orig_w, orig_h)
            
            painter.setBrush(QBrush(QColor(13, 15, 18, 180)))
            painter.setPen(QPen(QColor(255, 255, 255, 30), 1))
            painter.drawRoundedRect(orig_rect, 6, 6)
            painter.setPen(QPen(QColor("#9ca3af")))
            painter.drawText(orig_rect, Qt.AlignmentFlag.AlignCenter, orig_text)
            
            # RESULT (bottom right side, visible if split is active and after image loaded)
            if self.img_after and getattr(self, "show_split", True):
                result_text = "STAR MASK" if getattr(self, "preview_mode", "starless") == "mask" else "STARLESS"
                res_w = fm.horizontalAdvance(result_text) + 16
                res_h = fm.height() + 8
                res_rect = QRect(w - res_w - 12, h - res_h - 12, res_w, res_h)
                
                painter.setBrush(QBrush(QColor(13, 15, 18, 180)))
                painter.setPen(QPen(QColor(59, 130, 246, 180), 1))
                painter.drawRoundedRect(res_rect, 6, 6)
                painter.setPen(QPen(QColor("#3b82f6")))
                painter.drawText(res_rect, Qt.AlignmentFlag.AlignCenter, result_text)
                
            painter.restore()

        if self.is_selecting_roi and self.roi_start and self.roi_end:
            painter.save()
            painter.setPen(QPen(QColor(10, 132, 255, 180), 1, Qt.PenStyle.DashLine))
            painter.setBrush(Qt.BrushStyle.NoBrush)
            r = QRect(self.roi_start, self.roi_end)
            painter.drawRect(r)
            painter.restore()
        elif self.roi_rect:
            painter.save()
            p1 = self.image_to_widget_coords(self.roi_rect.topLeft())
            p2 = self.image_to_widget_coords(self.roi_rect.bottomRight())
            r = QRect(p1, p2).normalized()
            painter.setPen(QPen(QColor(10, 132, 255, 180), 1, Qt.PenStyle.DashLine))
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.drawRect(r)
            
            painter.setPen(QPen(QColor("#aeaeb2")))
            painter.drawText(r.topLeft() + QPoint(4, -4), "Preview Area")
            painter.restore()

        if self.zoom_factor > 1.0:
            painter.save()
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            
            zoom_text = f"Zoom: {int(self.zoom_factor * 100)}%"
            font = QFont("SF Pro Display", 10, QFont.Weight.Bold)
            painter.setFont(font)
            
            fm = painter.fontMetrics()
            text_width = fm.horizontalAdvance(zoom_text)
            text_height = fm.height()
            
            padding_x = 8
            padding_y = 4
            bubble_w = text_width + padding_x * 2
            bubble_h = text_height + padding_y * 2
            
            bubble_x = w - bubble_w - 12
            bubble_y = 12
            
            path = QPainterPath()
            path.addRoundedRect(bubble_x, bubble_y, bubble_w, bubble_h, 6, 6)
            
            painter.fillPath(path, QColor(0, 0, 0, 180))
            painter.setPen(QPen(QColor("#ffffff"), 1))
            painter.drawPath(path)
            
            painter.drawText(bubble_x + padding_x, bubble_y + padding_y + fm.ascent(), zoom_text)
            painter.restore()

    def update_tile(self, y: int, x: int, h: int, w: int, patch: np.ndarray, overlap: int):
        if not self.img_after or not self.img_before:
            return
        
        img_w = self.img_before.width()
        img_h = self.img_before.height()
        
        if self.accum_out is None or self.accum_out.shape[:2] != (img_h, img_w):
            self.accum_out = np.zeros((img_h, img_w, 3), dtype=np.float32)
            self.accum_weight = np.zeros((img_h, img_w, 1), dtype=np.float32)
        
        # Cosine weight mask
        ramp_y = np.ones(h, dtype=np.float32)
        if y > 0 and overlap > 0:
            ramp_y[:overlap] = 0.5 - 0.5 * np.cos(np.linspace(0.0, np.pi, overlap))
        if y + h < img_h and overlap > 0:
            ramp_y[-overlap:] = 0.5 - 0.5 * np.cos(np.linspace(np.pi, 0.0, overlap))

        ramp_x = np.ones(w, dtype=np.float32)
        if x > 0 and overlap > 0:
            ramp_x[:overlap] = 0.5 - 0.5 * np.cos(np.linspace(0.0, np.pi, overlap))
        if x + w < img_w and overlap > 0:
            ramp_x[-overlap:] = 0.5 - 0.5 * np.cos(np.linspace(np.pi, 0.0, overlap))

        mask_2d = ramp_y[:, None] * ramp_x[None, :]
        
        # Accumulate
        self.accum_out[y : y + h, x : x + w, :] += patch * mask_2d[..., None]
        self.accum_weight[y : y + h, x : x + w, :] += mask_2d[..., None]
        
        # Exact division out / weight
        w_clip = np.clip(self.accum_weight[y : y + h, x : x + w, :], 1e-8, None)
        blended_tile = self.accum_out[y : y + h, x : x + w, :] / w_clip
        
        blended_q = _rgb_to_qimage(blended_tile)
        
        painter = QPainter(self.img_after)
        painter.drawImage(x, img_h - y - h, blended_q)
        painter.end()
        self.update()

    def begin_tile_session(self, background: Optional[np.ndarray] = None):
        """Prepare self.img_after for tile updates by copying img_before or raw background."""
        self.accum_out = None
        self.accum_weight = None
        if background is not None:
            self.img_before = _rgb_to_qimage(background)
        if self.img_before:
            self.img_after = self.img_before.copy()
        self.update()


# ============================================================================
# Axiom V3 not-found dialog & helpers
# ============================================================================

def update_axiom3_path(engine_dir: Path):
    global AXIOM3_MODEL_PATH
    bundled_axiom3 = Path(__file__).resolve().parent.parent / "runs" / "axiom_v3" / "checkpoints" / "best.pt"
    if not bundled_axiom3.exists():
        bundled_axiom3 = Path(__file__).resolve().parent.parent / "runs" / "axiom_v3" / "checkpoints" / "test.pt"
    if not bundled_axiom3.exists():
        bundled_axiom3 = Path(__file__).resolve().parent.parent / "axiom3.pt"
    if not bundled_axiom3.exists():
        bundled_axiom3 = Path(__file__).resolve().parent.parent / "test.pt"
        
    if bundled_axiom3.exists():
        AXIOM3_MODEL_PATH = bundled_axiom3
    else:
        if (engine_dir / "axiom3.pt").exists():
            AXIOM3_MODEL_PATH = engine_dir / "axiom3.pt"
        elif (engine_dir / "test.pt").exists():
            AXIOM3_MODEL_PATH = engine_dir / "test.pt"
        else:
            AXIOM3_MODEL_PATH = engine_dir / "axiom3.pt" # default fallback


class Axiom3NotFoundDialog(QDialog):
    """Dialog shown when axiom3.pt or test.pt is not present in the model directory."""

    def __init__(self, parent=None, model_dir: Optional[Path] = None):
        super().__init__(parent)
        self.setWindowTitle("Axiom V3 Model Not Found")
        self.setModal(True)
        layout = QVBoxLayout()

        folder = str(model_dir) if model_dir else "the syqon_starless folder"
        info = QLabel(
            "Axiom V3 model (axiom3.pt or test.pt) was not found.\n\n"
            "To use the Axiom V3 model:\n"
            f"1. Copy axiom3.pt or test.pt into the folder:\n   {folder}\n\n"
            "Then click 'Check Again' or re-open the script."
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        btns = QHBoxLayout()
        check_btn = QPushButton("Check Again")
        check_btn.clicked.connect(self._check_again)
        btns.addWidget(check_btn)

        open_btn = QPushButton("Open Folder")
        open_btn.clicked.connect(lambda: QDesktopServices.openUrl(
            QUrl.fromLocalFile(str(model_dir)) if model_dir else QUrl()
        ))
        btns.addWidget(open_btn)

        cancel_btn = QPushButton("Cancel")
        cancel_btn.clicked.connect(self.reject)
        btns.addWidget(cancel_btn)

        layout.addLayout(btns)
        self.setLayout(layout)
        self._model_dir = model_dir

    def _check_again(self):
        if self._model_dir:
            update_axiom3_path(self._model_dir)
        p = AXIOM3_MODEL_PATH
        if p and p.exists():
            QMessageBox.information(self, "Found", f"{p.name} found! Axiom V3 is ready.")
            self.accept()
        else:
            QMessageBox.warning(self, "Not Found",
                f"axiom3.pt or test.pt still not found in:\n{self._model_dir}")


# Helpers: model install widget row
# ============================================================================

def _make_model_row(parent, label: str, path: Path, install_cb, remove_cb):
    """Returns (row_widget, status_label, btn_install, btn_remove) — status updates when path changes."""
    col = QWidget(parent)
    col.setObjectName("modelRowWidget")
    hlay = QHBoxLayout(col)
    hlay.setContentsMargins(10, 8, 10, 8)
    hlay.setSpacing(8)

    installed = path.exists() and path.is_file() if path else False
    color = '#30d158' if installed else '#ff453a'
    status_text = 'Installed' if installed else 'Missing'

    status = QLabel(col)
    status.setText(f"<span style='color:{color}; font-size: 12px;'>●</span> <span style='font-size: 11px; font-weight: bold; color: #ffffff;'>{label}:</span> <span style='color:{color}; font-size: 11px; font-weight: bold;'>{status_text}</span>")
    status.setStyleSheet("color:#ffffff; font-size:11px;")
    
    btn_i = QPushButton("Install", col)
    btn_i.setFixedWidth(64)
    btn_i.setFixedHeight(22)
    btn_i.setStyleSheet("QPushButton { font-size: 10px; padding: 2px 8px; min-height: 20px; font-weight: bold; background-color: #2563eb; color: #ffffff; border: none; border-radius: 4px; } QPushButton:hover { background-color: #1d4ed8; }")
    btn_i.clicked.connect(install_cb)
    
    btn_r = QPushButton("Remove", col)
    btn_r.setFixedWidth(64)
    btn_r.setFixedHeight(22)
    btn_r.setStyleSheet("QPushButton { font-size: 10px; padding: 2px 8px; min-height: 20px; font-weight: bold; background-color: #db2777; color: #ffffff; border: none; border-radius: 4px; } QPushButton:hover { background-color: #be185d; }")
    btn_r.clicked.connect(remove_cb)
    
    hlay.addWidget(status, 1)
    hlay.addWidget(btn_i)
    hlay.addWidget(btn_r)
    
    # Set initial visibility
    btn_i.setVisible(not installed)
    btn_r.setVisible(installed)
    
    return col, status, btn_i, btn_r


